1	import type { Page } from '@playwright/test';
2	
3	/**
4	 * Complete storage cleanup for test isolation.
5	 * Clears ALL storage mechanisms used by the app:
6	 * - localStorage (library index + all layout keys)
7	 * - sessionStorage (not currently used, but clean anyway)
8	 * - IndexedDB (not currently used, but clean for future-proofing)
9	 *
10	 * This replaces the simple `localStorage.clear()` pattern and prevents
11	 * cross-test pollution from the multi-layout library system.
12	 *
13	 * @param page - Playwright page instance
14	 */
15	export async function clearAllStorage(page: Page): Promise<void> {
16	  await page.evaluate(() => {
17	    // Clear localStorage completely
18	    localStorage.clear();
19	
20	    // Clear sessionStorage
21	    sessionStorage.clear();
22	
23	    // Clear all IndexedDB databases (async, but fire-and-forget)
24	    if (window.indexedDB && indexedDB.databases) {
25	      indexedDB.databases().then((dbs) => {
26	        dbs.forEach((db) => {
27	          if (db.name) indexedDB.deleteDatabase(db.name);
28	        });
29	      });
30	    }
31	  });
32	}
33	
34	/**
35	 * Wait for auto-save to complete after state changes.
36	 *
37	 * The app uses a 1000ms debounce (SAVE_DEBOUNCE_MS in useAutoSave.ts).
38	 * This replaces hard-coded `page.waitForTimeout(2000)` calls with
39	 * actual state observation - waits for the layout to actually be saved.
40	 *
41	 * **Replaces**:
